using System;

namespace DeltaniumApi.Models
{
    /// <summary>
    /// Represents a PRE rekey generated by author A for follower B
    /// Allows B to decrypt posts tagged with a specific policy (e.g., "followers:2025")
    /// </summary>
    public class UserRekey
    {
        public string Id { get; set; } = Guid.NewGuid().ToString();
        
        /// <summary>
        /// Public key of the author (A) who generated this rekey
        /// </summary>
        public string FollowingPubKey { get; set; } = string.Empty;
        
        /// <summary>
        /// Public key of the follower (B) who can use this rekey
        /// </summary>
        public string FollowerPubKey { get; set; } = string.Empty;
        
        /// <summary>
        /// Policy tag (e.g., "followers:2025") that this rekey is for
        /// </summary>
        public string Tag { get; set; } = string.Empty;
        
        /// <summary>
        /// Scope of the rekey: "tag" for policy-based, "file" for specific file
        /// </summary>
        public string Scope { get; set; } = "tag";
        
        /// <summary>
        /// Optional: Specific file ID if scope is "file"
        /// </summary>
        public string? FileId { get; set; }
        
        /// <summary>
        /// Base64-encoded rekey data: rk(A→B) for this tag
        /// Generated by A using their private key and B's public key
        /// </summary>
        public string RkBase64 { get; set; } = string.Empty;
        
        /// <summary>
        /// When this rekey was created
        /// </summary>
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        
        /// <summary>
        /// Optional: When this rekey expires (for key rotation)
        /// </summary>
        public DateTime? ExpiresAt { get; set; }
        
        /// <summary>
        /// Whether this rekey is still valid (can be revoked)
        /// </summary>
        public bool IsActive { get; set; } = true;
    }
}

